CREATE DATABASE IF NOT EXISTS annai_bhavan_catering CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE annai_bhavan_catering;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS menu_items(id INT AUTO_INCREMENT PRIMARY KEY,category VARCHAR(100) NOT NULL,name VARCHAR(150) NOT NULL,description VARCHAR(500),price DECIMAL(10,2),image_url VARCHAR(500),is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gallery(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200),event_name VARCHAR(150),image_url VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS videos(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,event_name VARCHAR(150),youtube_url VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS offers(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description VARCHAR(500),image_url VARCHAR(500),valid_until DATE,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews(id INT AUTO_INCREMENT PRIMARY KEY,customer_name VARCHAR(150) NOT NULL,rating INT NOT NULL,review_text VARCHAR(1000) NOT NULL,is_approved TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enquiries(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,phone VARCHAR(30) NOT NULL,event_type VARCHAR(100),event_date DATE,guests INT,location VARCHAR(250),message VARCHAR(1000),status ENUM('new','contacted','closed') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
